-- Viewmodel-recoil comparison variant of cw_anomaly_m16. Generated by work/build_vm_recoil.py.
-- Bolt motion measured from the viewmodel: "zatvor" in anm_shots, 3.024 units, peak frame 0, home frame 2 at 30 fps.

AddCSLuaFile()

SWEP.Base = "cw_anomaly_m16"

SWEP.PrintName = "M16A4 (VM recoil)"

SWEP.LuaViewmodelRecoil = true

SWEP.LuaViewmodelRecoilOverride = false

if CLIENT then
	SWEP.BoltBone = "zatvor"
	SWEP.BoltShootOffset = Vector(0, 0, 3.024)
	SWEP.BoltBonePositionRecoverySpeed = 46
	SWEP.HoldBoltWhileEmpty = true
	SWEP.DontHoldWhenReloading = true

	killicon.Add("cw_anomaly_m16_vmrecoil", "vgui/killicons/tfa_anomaly_m16", Color(255, 255, 255))
end

